   const own=hubState.taste.find(m=>m.id===movie.id&&m.owned),saved=movie.availabilitySnapshot;
   const fresh=saved&&!saved.stale&&Date.now()-(saved.checkedAt||0)<24*3600000;
   const offers=[...(own?HubModel.shelfStatus(own).offers:[]),...(fresh?saved.offers||[]:[])].filter(o=>o.kind==='physical'||o.kind==='free'||o.kind==='subscription'&&o.included||o.kind==='rent'&&typeof o.price==='number'&&o.price<=rentalBudget);
   if(!offers.length||deferred(movie,saved,'tonight'))continue;const cost=ReleaseModel.cost(offers,rentalBudget),fit=HubModel.affinity({...movie,meta:movie.meta||movie.detailsSnapshot},seeds,hubState.feedback),category=cost.offer.kind==='physical'?'physical':cost.offer.kind==='rent'?'rental':'included';
   const reason=movie.pinned?'You pinned this one.':fit.score>0?fit.reasons.join('. ')+'.':HubModel.watchlistPriority(movie)>0?'Newly included after a confirmed availability change.':category==='physical'?(isSeen(movie)?'Your own copy, ready for a rewatch.':'Your own copy. No rental checkout.'):category==='rental'?'A verified rental within your $'+rentalBudget.toFixed(2)+' limit.':'On your watchlist and included tonight.';
   eligible.push({movie,cost,category,reason,score:(movie.pinned?100:0)+fit.score+HubModel.watchlistPriority(movie)});
